# Calculate precision, recall, F1
predicted_raw = state.get('relations', [])
ground_truth_raw = state.get('ground_truth', [])

# CRITICAL: Normalize to list (relations may be a string)
if isinstance(predicted_raw, str):
    predicted_raw = [predicted_raw]
elif not isinstance(predicted_raw, list):
    predicted_raw = [predicted_raw]
if isinstance(ground_truth_raw, str):
    ground_truth_raw = [ground_truth_raw]
elif not isinstance(ground_truth_raw, list):
    ground_truth_raw = [ground_truth_raw]

pred_set = set()
for r in predicted_raw:
    if isinstance(r, dict):
        h = r.get('chemical', r.get('head','')).lower().strip()
        t = r.get('disease', r.get('tail','')).lower().strip()
        if h and t:
            pred_set.add((h,t))
    elif isinstance(r, str) and '|' in r:
        parts = r.split('|')
        if len(parts) >= 2:
            h = parts[0].lower().strip()
            t = parts[1].lower().strip()
            if h and t and h != 'chemical':
                pred_set.add((h,t))

gt_set = set()
for g in ground_truth_raw:
    if isinstance(g, dict):
        h = g.get('chemical', g.get('head','')).lower().strip()
        t = g.get('disease', g.get('tail','')).lower().strip()
        if h and t:
            gt_set.add((h,t))
    elif isinstance(g, str) and '|' in g:
        parts = g.split('|')
        if len(parts) >= 2:
            gt_set.add((parts[0].lower().strip(), parts[1].lower().strip()))

tp = len(pred_set & gt_set)
fp = len(pred_set - gt_set)
fn = len(gt_set - pred_set)
p = tp/(tp+fp) if (tp+fp)>0 else 0
r = tp/(tp+fn) if (tp+fn)>0 else 0
f1 = 2*p*r/(p+r) if (p+r)>0 else 0

